use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut sieve = Vec::new()
    let mut i: int = 0
    while i <= limit {
        sieve.push(true)
        i += 1
    }
    sieve[0] = false
    sieve[1] = false
    let mut p: int = 2
    while p * p <= limit {
        if sieve[p as usize] {
            let mut m = p * p
            while m <= limit {
                sieve[m as usize] = false
                m += p
            }
        }
        p += 1
    }
    let mut counts = Vec::new()
    let mut largest = Vec::new()
    let mut c: int = 0
    let mut last: int = 0
    let mut k: int = 0
    while k <= limit {
        if sieve[k as usize] {
            c += 1
            last = k
        }
        counts.push(c)
        largest.push(last)
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t == "" {
            continue
        }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n as usize]} ${largest[n as usize]}")
        }
    }
}

